patch_animation_effects.code:
final response = await client.animationEffects.patchAnimationEffects({
  'animation_effects': {
    'page_transition': {'animation_before_entering_new_page': true},
    'image_lazy_effect': {'blog_list_image_lazy_effect': true},
  },
});
final animationEffects = (response.map as Map)['animation_effects'] as Map;
print(animationEffects['page_transition']);
print(animationEffects['image_lazy_effect']);

